window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6f59e939b1f2ea9f"]={"versions": [{"id": "FIG-6f59e939b1f2ea9f", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Mengen-/Verschachtelungsdiagramm im Kontext des AUTOSAR Classic Platform Communication Stack (AUTOSAR COM). Das Diagramm illustriert das organisatorische Konzept der Gruppierung von Interaction Layer Protocol Data Units (I-PDUs) innerhalb hierarchischer I-PDU-Gruppen zur gemeinsamen Steuerung im Kommunikationsmanagement.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>I-PDU group A</strong>: Übergeordnete I-PDU-Gruppe (äußerer Container).</li>\n<li><strong>I-PDU group B</strong>: Untergeordnete I-PDU-Gruppe innerhalb von Gruppe A, enthält die Entitäten <code>I-PDU 1</code> und <code>I-PDU 2</code>.</li>\n<li><strong>I-PDU group C</strong>: Untergeordnete I-PDU-Gruppe innerhalb von Gruppe A, enthält die Entität <code>I-PDU 3</code>.</li>\n<li><strong>I-PDU 1, I-PDU 2, I-PDU 3</strong>: Diskrete Protokolldateneinheiten (I-PDUs), die den jeweiligen Untergruppen zugeordnet sind.</li>\n<li>Schnittstellen: Keine softwaretechnischen APIs oder Ports dargestellt; rein strukturelle Enthaltenseins-Relation.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Zeitachsen oder Sequenzen. Die dargestellte Hierarchie impliziert Steuerungsabhängigkeiten: Die Aktivierung oder Deaktivierung einer übergeordneten Gruppe (Gruppe A) schließt funktionell die Steuerung der enthaltenen Untergruppen (Gruppe B, Gruppe C) und deren zugewiesene I-PDUs ein.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulichung der Konfigurationssemantik für AUTOSAR COM bezüglich geschachtelter I-PDU-Gruppen (COM206, COM126, COM216). Relevanz für Systemdesigner und COM-Konfiguratoren: I-PDUs müssen nicht zwingend flach gruppiert werden, sondern lassen sich über Subgruppen hierarchisch strukturieren, um gemeinsame Start-/Stopp-Mechanismen für Funktionsdomänen zu realisieren.</p>"}, {"id": "FIG-f39b44c33ca521e1", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Mengen-/Verschachtelungsdiagramm im Kontext des AUTOSAR Classic Platform Communication Stack (AUTOSAR COM). Das Diagramm illustriert das organisatorische Konzept der Gruppierung von Interaction Layer Protocol Data Units (I-PDUs) innerhalb hierarchischer I-PDU-Gruppen zur gemeinsamen Steuerung im Kommunikationsmanagement.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>I-PDU group A</strong>: Übergeordnete I-PDU-Gruppe (äußerer Container).</li>\n<li><strong>I-PDU group B</strong>: Untergeordnete I-PDU-Gruppe innerhalb von Gruppe A, enthält die Entitäten <code>I-PDU 1</code> und <code>I-PDU 2</code>.</li>\n<li><strong>I-PDU group C</strong>: Untergeordnete I-PDU-Gruppe innerhalb von Gruppe A, enthält die Entität <code>I-PDU 3</code>.</li>\n<li><strong>I-PDU 1, I-PDU 2, I-PDU 3</strong>: Diskrete Protokolldateneinheiten (I-PDUs), die den jeweiligen Untergruppen zugeordnet sind.</li>\n<li>Schnittstellen: Keine softwaretechnischen APIs oder Ports dargestellt; rein strukturelle Enthaltenseins-Relation.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Zeitachsen oder Sequenzen. Die dargestellte Hierarchie impliziert Steuerungsabhängigkeiten: Die Aktivierung oder Deaktivierung einer übergeordneten Gruppe (Gruppe A) schließt funktionell die Steuerung der enthaltenen Untergruppen (Gruppe B, Gruppe C) und deren zugewiesene I-PDUs ein.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulichung der Konfigurationssemantik für AUTOSAR COM bezüglich geschachtelter I-PDU-Gruppen (COM206, COM126, COM216). Relevanz für Systemdesigner und COM-Konfiguratoren: I-PDUs müssen nicht zwingend flach gruppiert werden, sondern lassen sich über Subgruppen hierarchisch strukturieren, um gemeinsame Start-/Stopp-Mechanismen für Funktionsdomänen zu realisieren.</p>"}, {"id": "FIG-0d26faccd10f97d0", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Gerichteter Zuordnungs- und Aktivierungsgraph im Kontext des AUTOSAR COM Kommunikationsmanagements und BswM/EcuM-Modusmanagements. Das Diagramm modelliert die Abhängigkeiten zwischen Fahrzeug- bzw. Systemmodi, logischen Funktionen, Übertragungsrichtungen auf physischen/logischen Busschnittstellen und den zugehörigen I-PDU-Mengen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Modus-Entitäten (orange Ovale)</strong>: <code>Mode1</code>, <code>Mode2</code>, <code>Mode3</code>.</li>\n<li><strong>Funktions-Entitäten (gelbe Ovale)</strong>: <code>Function1</code>, <code>Function2</code>, <code>Function3</code>.</li>\n<li><strong>Bus- und Richtungs-Knoten (blaue und olivgrüne Ovale, deklariert als I-PDU groups)</strong>:</li>\n<li>Bus 1: <code>BUS1</code>, <code>BUS1 RX</code>, <code>BUS1 TX</code>.</li>\n<li>Bus 2: <code>BUS2</code>, <code>BUS2 RX</code>, <code>BUS2 TX</code>.</li>\n<li><strong>I-PDU-Mengen / PDU-Container (grüne gestapelte Rechtecke)</strong>:</li>\n<li>Bus 1 RX/TX: <code>BUS1 RX Function1</code>, <code>BUS1 TX Function1</code>, <code>BUS2 RX Function1 / Function2</code>, <code>BUS1 RX Function2</code>, <code>BUS1 TX Function2</code>.</li>\n<li>Bus 2 RX/TX: <code>BUS2 RX Function2</code>, <code>BUS2 TX Function2</code>, <code>BUS RX Function3</code>, <code>BUS2 TX Function3</code>.</li>\n<li><strong>Legende / Notizen</strong>:</li>\n<li>Oval: <code>I-PDU group</code>.</li>\n<li>Gestapeltes Rechteck: <code>I-PDUs</code>.</li>\n<li>Pfeil: <code>includes</code>.</li>\n<li>Regelkasten: Semantikregeln für Gruppenzugehörigkeit und Aktivierungszustand.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablaufsteuerung basierend auf Moduswechseln:</p>\n<ol class=\"fig-list\">\n<li>Ein aktiver Betriebsmodus (<code>Mode1</code> bis <code>Mode3</code>) aktiviert die zugeordneten Funktionen (<code>Function1</code> bis <code>Function3</code>). <code>Mode2</code> adressiert beispielsweise <code>Function2</code> und <code>Function3</code>.</li>\n<li>Funktionen referenzieren spezifische funktionale I-PDU-Gruppen und PDU-Cluster sowohl in Senderichtung (TX) als auch in Empfangsrichtung (RX).</li>\n<li>Die Aktivierung von I-PDUs folgt der formalen Boole'schen Bedingung: Eine I-PDU kann beliebigen I-PDU-Gruppen angehören; eine I-PDU ist genau dann aktiv („active iff“), wenn mindestens eine I-PDU-Gruppe aktiv ist, der sie angehört (ODER-Verknüpfung der Gruppenaktivierungen).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Auslegungsregel für die COM-Implementierung von Gruppenstart und -stopp:</p>\n<ul class=\"fig-list\">\n<li>Unterstützung von n:m-Beziehungen zwischen I-PDUs und I-PDU-Gruppen.</li>\n<li>Entkopplung von Bus-Topologie (<code>BUS1</code>, <code>BUS2</code>) und funktionalen Software-Modi (<code>Mode1</code>..<code>Mode3</code>).</li>\n<li>Relevanz für COM- und BswM-Konfiguration: Das Senden/Empfangen von I-PDUs wird deterministisch über Modusmanager-Aktionen geschaltet, wobei geteilte PDUs aktiv bleiben, solange mindestens ein referenzierender Pfad aktiv geschaltet ist.</li>\n</ul>"}, {"id": "FIG-734e4bdde5e40bea", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Gerichteter Zuordnungs- und Aktivierungsgraph im Kontext des AUTOSAR COM Kommunikationsmanagements und BswM/EcuM-Modusmanagements. Das Diagramm modelliert die Abhängigkeiten zwischen Fahrzeug- bzw. Systemmodi, logischen Funktionen, Übertragungsrichtungen auf physischen/logischen Busschnittstellen und den zugehörigen I-PDU-Mengen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Modus-Entitäten (orange Ovale)</strong>: <code>Mode1</code>, <code>Mode2</code>, <code>Mode3</code>.</li>\n<li><strong>Funktions-Entitäten (gelbe Ovale)</strong>: <code>Function1</code>, <code>Function2</code>, <code>Function3</code>.</li>\n<li><strong>Bus- und Richtungs-Knoten (blaue und olivgrüne Ovale, deklariert als I-PDU groups)</strong>:</li>\n<li>Bus 1: <code>BUS1</code>, <code>BUS1 RX</code>, <code>BUS1 TX</code>.</li>\n<li>Bus 2: <code>BUS2</code>, <code>BUS2 RX</code>, <code>BUS2 TX</code>.</li>\n<li><strong>I-PDU-Mengen / PDU-Container (grüne gestapelte Rechtecke)</strong>:</li>\n<li>Bus 1 RX/TX: <code>BUS1 RX Function1</code>, <code>BUS1 TX Function1</code>, <code>BUS2 RX Function1 / Function2</code>, <code>BUS1 RX Function2</code>, <code>BUS1 TX Function2</code>.</li>\n<li>Bus 2 RX/TX: <code>BUS2 RX Function2</code>, <code>BUS2 TX Function2</code>, <code>BUS RX Function3</code>, <code>BUS2 TX Function3</code>.</li>\n<li><strong>Legende / Notizen</strong>:</li>\n<li>Oval: <code>I-PDU</code> / <code>group</code> (zweizeilig umbrochen).</li>\n<li>Gestapeltes Rechteck: <code>I-PDUs</code>.</li>\n<li>Pfeil: <code>includes</code>.</li>\n<li>Regelkasten: Textliche Spezifikation der Aktivierungslogik mit unvollständigem Satzende im zweiten Punkt („an I-Pdu is active iff any I- Pdu-group is active it belongs“).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablaufsteuerung basierend auf Moduswechseln:</p>\n<ol class=\"fig-list\">\n<li>Ein aktiver Betriebsmodus (<code>Mode1</code> bis <code>Mode3</code>) aktiviert die zugeordneten Funktionen (<code>Function1</code> bis <code>Function3</code>). <code>Mode2</code> adressiert beispielsweise <code>Function2</code> und <code>Function3</code>.</li>\n<li>Funktionen referenzieren spezifische funktionale I-PDU-Gruppen und PDU-Cluster sowohl in Senderichtung (TX) als auch in Empfangsrichtung (RX).</li>\n<li>Die Aktivierung von I-PDUs folgt der formalen Boole'schen Bedingung: Eine I-PDU kann beliebigen I-PDU-Gruppen angehören; eine I-PDU ist genau dann aktiv („active iff“), wenn mindestens eine I-PDU-Gruppe aktiv ist, der sie angehört (ODER-Verknüpfung der Gruppenaktivierungen).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Auslegungsregel für die COM-Implementierung von Gruppenstart und -stopp:</p>\n<ul class=\"fig-list\">\n<li>Unterstützung von n:m-Beziehungen zwischen I-PDUs und I-PDU-Gruppen.</li>\n<li>Entkopplung von Bus-Topologie (<code>BUS1</code>, <code>BUS2</code>) und funktionalen Software-Modi (<code>Mode1</code>..<code>Mode3</code>).</li>\n<li>Relevanz für COM- und BswM-Konfiguration: Das Senden/Empfangen von I-PDUs wird deterministisch über Modusmanager-Aktionen geschaltet, wobei geteilte PDUs aktiv bleiben, solange mindestens ein referenzierender Pfad aktiv geschaltet ist.</li>\n</ul>"}, {"id": "FIG-91f5abc6eba40f97", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Gerichteter Zuordnungs- und Aktivierungsgraph im Kontext des AUTOSAR COM Kommunikationsmanagements und BswM/EcuM-Modusmanagements. Das Diagramm modelliert die Abhängigkeiten zwischen Fahrzeug- bzw. Systemmodi, logischen Funktionen, Übertragungsrichtungen auf physischen/logischen Busschnittstellen und den zugehörigen I-PDU-Mengen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Modus-Entitäten (orange Ovale)</strong>: <code>Mode1</code>, <code>Mode2</code>, <code>Mode3</code>.</li>\n<li><strong>Funktions-Entitäten (gelbe Ovale)</strong>: <code>Function1</code>, <code>Function2</code>, <code>Function3</code>.</li>\n<li><strong>Bus- und Richtungs-Knoten (blaue und olivgrüne Ovale, deklariert als I-PDU groups)</strong>:</li>\n<li>Bus 1: <code>BUS1</code>, <code>BUS1 RX</code>, <code>BUS1 TX</code>.</li>\n<li>Bus 2: <code>BUS2</code>, <code>BUS2 RX</code>, <code>BUS2 TX</code>.</li>\n<li><strong>I-PDU-Mengen / PDU-Container (grüne gestapelte Rechtecke)</strong>:</li>\n<li>Bus 1 RX/TX: <code>BUS1 RX Function1</code>, <code>BUS1 TX Function1</code>, <code>BUS2 RX Function1 / Function2</code>, <code>BUS1 RX Function2</code>, <code>BUS1 TX Function2</code>.</li>\n<li>Bus 2 RX/TX: <code>BUS2 RX Function2</code>, <code>BUS2 TX Function2</code>, <code>BUS RX Function3</code>, <code>BUS2 TX Function3</code>.</li>\n<li><strong>Legende / Notizen</strong>:</li>\n<li>Oval: <code>I-PDU</code> / <code>group</code> (zweizeilig).</li>\n<li>Gestapeltes Rechteck: <code>I-PDUs</code>.</li>\n<li>Pfeil: <code>includes</code>.</li>\n<li>Regelkasten: Textliche Spezifikation der Aktivierungslogik mit vollständiger Formulierung im zweiten Punkt („an I-Pdu is active iff any I-Pdu-group is active it belongs to“).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablaufsteuerung basierend auf Moduswechseln:</p>\n<ol class=\"fig-list\">\n<li>Ein aktiver Betriebsmodus (<code>Mode1</code> bis <code>Mode3</code>) aktiviert die zugeordneten Funktionen (<code>Function1</code> bis <code>Function3</code>). <code>Mode2</code> adressiert beispielsweise <code>Function2</code> und <code>Function3</code>.</li>\n<li>Funktionen referenzieren spezifische funktionale I-PDU-Gruppen und PDU-Cluster sowohl in Senderichtung (TX) als auch in Empfangsrichtung (RX).</li>\n<li>Die Aktivierung von I-PDUs folgt der formalen Boole'schen Bedingung: Eine I-PDU kann beliebigen I-PDU-Gruppen angehören; eine I-PDU ist genau dann aktiv („active iff“), wenn mindestens eine I-PDU-Gruppe aktiv ist, der sie angehört (ODER-Verknüpfung der Gruppenaktivierungen).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Auslegungsregel für die COM-Implementierung von Gruppenstart und -stopp:</p>\n<ul class=\"fig-list\">\n<li>Unterstützung von n:m-Beziehungen zwischen I-PDUs und I-PDU-Gruppen.</li>\n<li>Entkopplung von Bus-Topologie (<code>BUS1</code>, <code>BUS2</code>) und funktionalen Software-Modi (<code>Mode1</code>..<code>Mode3</code>).</li>\n<li>Relevanz für COM- und BswM-Konfiguration: Das Senden/Empfangen von I-PDUs wird deterministisch über Modusmanager-Aktionen geschaltet, wobei geteilte PDUs aktiv bleiben, solange mindestens ein referenzierender Pfad aktiv geschaltet ist.</li>\n</ul>"}], "trans": [{"from": "FIG-6f59e939b1f2ea9f", "to": "FIG-f39b44c33ca521e1", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Layout/Zuschnitt: Oberer Randanschnitt mit Fließtextfragmenten („oups see COM206, COM126 and COM216.“) wurde im Bildausschnitt entfernt.</li>\n<li>Die diagrammatischen Elemente (I-PDU group A/B/C, I-PDU 1/2/3) sind strukturell und inhaltlich unverändert.</li>\n</ul>"}, {"from": "FIG-f39b44c33ca521e1", "to": "FIG-0d26faccd10f97d0", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Diagrammtyp und Modellierung grundlegend umgestellt: Das Zylinder-/Mengendiagramm für hierarchische Schachtelung von I-PDU-Gruppen wurde durch ein gerichtetes Graphendiagramm (Zustands-/Modus- und Routing-Zuordnung) ersetzt.</li>\n<li>Entitäten: Abstrakte Gruppen (I-PDU group A/B/C) und PDUs (I-PDU 1/2/3) wurden durch konkrete Bus-Cluster (<code>BUS1</code>, <code>BUS2</code>), Kommunikationsrichtungen (<code>BUS1 RX</code>, <code>BUS1 TX</code>, <code>BUS2 RX</code>, <code>BUS2 TX</code>), PDU-Stapel pro Bus/Richtung/Funktion sowie Applikationsmodi (<code>Mode1</code>, <code>Mode2</code>, <code>Mode3</code>) und Funktionen (<code>Function1</code>, <code>Function2</code>, <code>Function3</code>) ersetzt.</li>\n<li>Relationen & Legende: Einführung von gerichteten Kanten für Modus-Aktivierung und PDU-Inklusion (<code>includes</code>) sowie formalen Semantikregeln bezüglich Gruppenaktivierung und Mehrfachzuordnung.</li>\n</ul>"}, {"from": "FIG-0d26faccd10f97d0", "to": "FIG-734e4bdde5e40bea", "fr": "R3.2.3", "tr": "R4.0.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Textkasten unten rechts: Im zweiten Aufzählungspunkt wurde das Wort „to“ am Zeilenende abgeschnitten bzw. entfernt („is active it belongs“ statt „is active it belongs to“).</li>\n<li>Legende oben links: Trennung/Zeilenumbruch von „I-PDU group“ in „I-PDU“ und „group“.</li>\n<li>Geringfügige Bildgrößenanpassung (964x817 auf 941x813 Pixel) durch Neuberechnung des Randausschnitts.</li>\n</ul>"}, {"from": "FIG-734e4bdde5e40bea", "to": "FIG-91f5abc6eba40f97", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Textkasten unten rechts: Korrektur des Textabbruchs im zweiten Aufzählungspunkt durch Silbentrennung und Ergänzung von „to“ („is active it belongs to“ mit getrenntem „ac-tive“).</li>\n</ul>"}]};
